{
  "root_causes": [
    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) AS mn, round(avg(value),2) AS deployment_available FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND attr_k8s_deployment_name='recommendation' GROUP BY 1 ORDER BY 1", "claim": "recommendation deployment availability drops from 1 to 0 for the whole abnormal window and stays there."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) AS n FROM abnormal_traces WHERE span_name LIKE 'recommendation.Recommendation/%' OR service_name='recommendation' GROUP BY ALL", "claim": "recommendation server spans vanish in the abnormal window; only frontend's client-side calls remain."},
        {"kind": "trace", "sql": "SELECT span_name, attr_http_response_status_code, count(*) AS n, round(median(duration)/1e3,1) AS med_us FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /recommendations' GROUP BY ALL", "claim": "Frontend /recommendations returns 500 about 590 times, failing in tens of microseconds, not after a timeout."}
      ]
    },
    {
      "service": "profile",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) AS mn, round(avg(value),3) AS container_cpu FROM abnormal_metrics WHERE service_name='profile' AND metric='container.cpu.usage' GROUP BY 1 ORDER BY 1", "claim": "profile container CPU jumps from about 0.007 to a flat ~2.6 cores from 09:37 onward, pinned at a ceiling."},
        {"kind": "trace", "sql": "WITH c AS (SELECT span_id, duration cd FROM abnormal_traces WHERE service_name='frontend' AND span_name='profile.Profile/GetProfiles'), s AS (SELECT parent_span_id, duration sd FROM abnormal_traces WHERE service_name='profile' AND attr_span_kind='Server') SELECT round(median(cd-sd)/1e6,2) AS gap_ms_median FROM c JOIN s ON c.span_id=s.parent_span_id", "claim": "Frontend-to-profile call overhead outside profile's handler rises to about 1.5 ms (normal 0.3 ms), consistent with queueing on a saturated pod."},
        {"kind": "trace", "sql": "SELECT span_name, count(*) AS n, round(median(duration)/1e6,2) AS med_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','profile.Profile/GetProfiles') GROUP BY ALL", "claim": "Frontend /hotels median latency rises from about 2.5 ms to 7.8 ms in the abnormal window."}
      ]
    }
  ],
  "propagation": [
    {"from": "recommendation", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT attr_http_response_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /recommendations' GROUP BY 1", "claim": "The recommendation outage shows up as HTTP 500 responses on frontend's /recommendations endpoint."}]},
    {"from": "profile", "to": "frontend", "evidence": [{"kind": "trace", "sql": "SELECT date_trunc('minute', time) AS mn, round(median(duration)/1e6,2) AS hotels_med_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='HTTP /hotels' GROUP BY 1 ORDER BY 1", "claim": "Frontend /hotels is slower in the abnormal window, while its profile calls wait longer on the caller side."}]}
  ]
}
